<?php
require_once __DIR__ . '/../app/bootstrap.php'; require_once __DIR__ . '/../app/controllers/AdminFeatureController.php';
if (!Auth::check()) { header('Location: ' . APP_URL . '/admin-private-dnstl/login.php'); exit; } if (Auth::userRole() !== 'admin') { header('Location: ' . APP_URL . '/user-junkshop/dashboard.php'); exit; }
$pdo = Database::getInstance()->getPDO();
$pdo->prepare('UPDATE concerns SET is_read_admin = 1 WHERE is_read_admin = 0')->execute();
$currentCooldownHours = (int) ($pdo->query('SELECT concern_cooldown_hours FROM fee_settings ORDER BY id ASC LIMIT 1')->fetchColumn() ?: 24);
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['save_cooldown'])) {
    if (!CSRF::verify($_POST['_csrf_token'] ?? '')) {
        $_SESSION['flash_message'] = 'Security token expired. Please try again.';
        $_SESSION['flash_type'] = 'danger';
        header('Location: concerns.php');
        exit;
    }
    $newCooldown = max(0, (int) ($_POST['concern_cooldown_hours'] ?? 0));
    $pdo->prepare('UPDATE fee_settings SET concern_cooldown_hours = :concern_cooldown_hours, updated_at = CURRENT_TIMESTAMP WHERE id = 1')->execute(['concern_cooldown_hours' => $newCooldown]);
    $_SESSION['flash_message'] = 'Anti-spam cooldown set to ' . $newCooldown . ' hours.';
    $_SESSION['flash_type'] = 'success';
    header('Location: concerns.php');
    exit;
}
$controller = new AdminFeatureController(); $feedback = null; if ($_SERVER['REQUEST_METHOD'] === 'POST' && CSRF::verify()) $feedback = $controller->updateConcern((int) $_POST['concern_id'], (string) $_POST['status'], (string) ($_POST['admin_note'] ?? '')); $concerns = $controller->listConcerns(); $pageTitle = 'Concerns & Disputes'; $activePage = 'concerns'; ob_start();
?><div class="card border-0 shadow-sm mb-4"><div class="card-body p-4"><div class="d-flex flex-column flex-md-row justify-content-between align-items-md-center gap-3"><div><h5 class="fw-bold mb-1">Cooldown Configuration</h5><p class="text-muted mb-0">Set the minimum wait time before a user can submit another concern.</p></div><div class="d-flex align-items-center gap-2"><form method="post" class="d-flex align-items-center gap-2 mb-0"><?php echo CSRF::field(); ?><input type="hidden" name="save_cooldown" value="1"><label class="form-label mb-0" for="concern_cooldown_hours">Hours</label><input class="form-control" type="number" id="concern_cooldown_hours" name="concern_cooldown_hours" min="0" step="1" value="<?php echo (int) $currentCooldownHours; ?>"><button class="btn btn-primary" type="submit">Save Cooldown</button></form></div></div></div></div><div class="card border-0 shadow-sm"><div class="card-body p-4"><h2 class="fw-bold mb-1">Concerns & Disputes</h2><p class="text-muted mb-4">Review basic support tickets submitted by sellers and junkshop partners.</p><?php if ($feedback): ?><div class="alert alert-<?php echo $feedback['success'] ? 'success' : 'danger'; ?>"><?php echo Validator::escape($feedback['message']); ?></div><?php endif; ?><div class="table-responsive"><table class="table table-hover align-middle"><thead class="table-light"><tr><th>Reporter</th><th>Concern</th><th>Status</th><th>Admin resolution</th></tr></thead><tbody><?php foreach ($concerns as $concern): ?><tr><td><?php echo Validator::escape($concern['reporter_name'] ?? $concern['reporter_email']); ?><br><span class="badge text-bg-light border"><?php echo Validator::escape($concern['reporter_role'] ?? 'Seller'); ?></span><br><span class="small text-muted"><?php echo Validator::escape($concern['reporter_email']); ?></span></td><td><strong><?php echo Validator::escape($concern['subject']); ?></strong><br><span class="small"><?php echo nl2br(Validator::escape($concern['description'])); ?></span></td><td><span class="badge text-bg-secondary"><?php echo Validator::escape($concern['status']); ?></span><br><span class="small text-muted"><?php echo Validator::escape(!empty($concern['created_at']) ? date('M d, Y g:i A', strtotime($concern['created_at'])) : 'Unknown'); ?></span></td><td><form method="post"><input type="hidden" name="_csrf_token" value="<?php echo CSRF::token(); ?>"><input type="hidden" name="concern_id" value="<?php echo (int) $concern['id']; ?>"><select class="form-select form-select-sm mb-2" name="status"><option <?php echo $concern['status'] === 'Open' ? 'selected' : ''; ?>>Open</option><option <?php echo $concern['status'] === 'In Review' ? 'selected' : ''; ?>>In Review</option><option <?php echo $concern['status'] === 'Resolved' ? 'selected' : ''; ?>>Resolved</option><option <?php echo $concern['status'] === 'Closed' ? 'selected' : ''; ?>>Closed</option></select><textarea class="form-control form-control-sm mb-2" name="admin_note" rows="2" placeholder="Resolution note"><?php echo Validator::escape($concern['admin_note'] ?? ''); ?></textarea><button class="btn btn-sm btn-primary">Save</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></div><?php $content = ob_get_clean(); require_once __DIR__ . '/../app/views/admin_dashboard_shell.php';